function Save-Json([string]$Name,$Value){$Value|ConvertTo-Json -Depth 100|Set-Content -LiteralPath(Join-Path $EvidenceRoot $Name) -Encoding utf8}
function Save-ExternalJson([string]$Path,$Value){$Value|ConvertTo-Json -Depth 100|Set-Content -LiteralPath $Path -Encoding utf8}
function Sha ([string]$Path){(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()}
function Sha-Text([string]$Value){$b=[Text.Encoding]::UTF8.GetBytes($Value);$h=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($h.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Git-Text([string[]]$Arguments) { $o=&git -C $RepoRoot @Arguments 2>&1; if($LASTEXITCODE -ne 0){throw "GIT_COMMAND_FAILURE $($Arguments -join ' ')"}; ($o|ForEach-Object ToString) -join [Environment]::NewLine }
function Git-Lines([string[]]$Arguments) { $t=Git-Text $Arguments; if([string]::IsNullOrWhiteSpace($t)){return @()}; @($t -split '\r?\n'|Where-Object{ -not [string]::IsNullOrWhiteSpace($_)}) }
function Check([string]$Id,[bool]$Pass,$Actual='') { $Checks.Add([ordered]@{id=$Id;phase=$ExecutionPhase;result=if($Pass){'PASS'}else{'FAIL'};actual=[string]$Actual}); if(-not $Pass){$script:FailureCode=$Id;throw "VALIDATION_FAILURE [$Id] $Actual"} }
function Invoke-AzRead([string[]]$Arguments,[string]$Label) { $script:ExecutionPhase='AZURE_READONLY_PREFLIGHT';$script:AzureReadPhaseEntered=$true;$script:AzureReadCommands++;$o=&az @Arguments --only-show-errors 2>&1;if($LASTEXITCODE -ne 0){throw "AZURE_READ_COMMAND_FAILURE [$Label]"};($o|ForEach-Object ToString)-join [Environment]::NewLine }
function Invoke-AzReadJson([string[]]$Arguments,[string]$Label) { $t=Invoke-AzRead $Arguments $Label;$s=@($t.IndexOf('{'),$t.IndexOf('['))|Where-Object{$_ -ge 0}|Sort-Object;if($s.Count -eq 0){throw "AZURE_READ_JSON_EMPTY [$Label]"};$t.Substring($s[0])|ConvertFrom-Json }
function Invoke-AzMutation([string[]]$Arguments,[string]$Label,[string]$Counter) { $script:ExecutionPhase=if($Counter -like '*SQL*'){'SQL_ADMIN_SWITCH'}elseif($Counter -eq 'BOOTSTRAP_JOB_CREATES'){'JOB_CREATE'}elseif($Counter -eq 'BOOTSTRAP_JOB_EXECUTIONS'){'BOOTSTRAP_START_REQUEST'}else{'AZURE_MUTATION'};$script:AzureMutationOccurred=$true;$script:AzureMutationCommands++;$script:MutationCounts[$Counter]++;$o=&az @Arguments --only-show-errors 2>&1;if($LASTEXITCODE -ne 0){throw "AZURE_MUTATION_COMMAND_FAILURE [$Label]"};($o|ForEach-Object ToString)-join [Environment]::NewLine }
function Invoke-AzRestRead([string]$SubscriptionId,[string]$Url,[string]$Label) { Invoke-AzRead @('rest','--subscription',$SubscriptionId,'--method','get','--url',$Url,'--output','json') $Label|ConvertFrom-Json }
function Invoke-AzRestPut([string]$SubscriptionId,[string]$Url,[string]$BodyPath,[string]$Label,[string]$Counter) { Invoke-AzMutation @('rest','--subscription',$SubscriptionId,'--method','put','--url',$Url,'--body',"@$BodyPath",'--output','json') $Label $Counter|Out-Null }
function Read-Manifest([string]$Root,[string[]]$ExpectedNames) { $p=Join-Path $Root 'MANIFEST.sha256';if(-not(Test-Path -LiteralPath $p)){return $null};$rows=@();foreach($line in @(Get-Content -LiteralPath $p)){if($line -match '^([0-9a-f]{64})  (.+)$'){$rows+=[pscustomobject]@{expected=$Matches[1];name=$Matches[2]}}};$names=@($rows|ForEach-Object{$_.name});$missing=@($ExpectedNames|Where-Object{$names -notcontains $_});$unexpected=@($names|Where-Object{$ExpectedNames -notcontains $_});$duplicate=$names.Count-(@($names|Sort-Object -Unique)).Count;$matched=0;$failed=0;foreach($r in $rows){$f=Join-Path $Root $r.name;if((Test-Path -LiteralPath $f) -and (Sha $f) -eq $r.expected){$matched++}else{$failed++}};[ordered]@{root=$Root;expectedNames=$ExpectedNames;rows=$rows;expectedMembers=$ExpectedNames.Count;foundMembers=$rows.Count;missing=$missing;unexpected=$unexpected;duplicate=$duplicate;matchedMembers=$matched;failedMembers=$failed;manifestSha=Sha $p;pass=($missing.Count -eq 0 -and $unexpected.Count -eq 0 -and $duplicate -eq 0 -and $rows.Count -eq $ExpectedNames.Count -and $matched -eq $ExpectedNames.Count -and $failed -eq 0)} }
function Find-V24Evidence { $dirs=@();foreach($root in @('/tmp',[IO.Path]::GetTempPath())|Select-Object -Unique){if(Test-Path -LiteralPath $root){$dirs+=@(Get-ChildItem -LiteralPath $root -Directory -Filter 'ProposalOps_Azure_P0_V2_4_*' -ErrorAction SilentlyContinue)}};$valid=@();foreach($dir in @($dirs|Sort-Object FullName -Unique)){try{$fp=Join-Path $dir.FullName '13_FINAL_RESULT.json';if(-not(Test-Path -LiteralPath $fp)){continue};$f=Get-Content -LiteralPath $fp -Raw|ConvertFrom-Json;$m=Read-Manifest $dir.FullName $V24Members;if($m -and $f.FINAL_RESULT -eq 'V2_4_MI_TOKEN_DIAGNOSTIC_PASS' -and $m.pass -and $f.AZURE_IDENTITY_CORROBORATION -eq 'FAIL' -and -not[bool]$f.CROSS_TRACK_CONVERGENCE_AUTHORIZED -and [int]$f.REAL_AMEC_DATA_READS -eq 0 -and [int]$f.REAL_AMEC_DATA_WRITES -eq 0){$valid+=[pscustomobject]@{root=$dir.FullName;final=$f;manifest=$m}}}catch{}};if($valid.Count -eq 0){throw 'V24_EVIDENCE_NOT_FOUND'};if(@($valid|ForEach-Object{$_.manifest.manifestSha}|Select-Object -Unique).Count -ne 1){throw 'V24_EVIDENCE_AMBIGUOUS'};$valid[0] }
function Verify-V24([string]$Root,[string]$ManifestSha) { $m=Read-Manifest $Root $V24Members;if(-not$m.pass -or $m.manifestSha -ne $ManifestSha){throw 'V24_POST_RUN_INTEGRITY_FAILURE'};[ordered]@{result='PASS';root=$Root;manifestSha=$m.manifestSha;expectedMembers=$m.expectedMembers;foundMembers=$m.foundMembers} }
function Test-Admin([object]$A,[object]$E) { $null -ne $A -and [string]$A.properties.administratorType -eq [string]$E.properties.administratorType -and [string]$A.properties.login -eq [string]$E.properties.login -and [string]$A.properties.sid -eq [string]$E.properties.sid -and [string]$A.properties.tenantId -eq [string]$E.properties.tenantId }
function Get-Admin([string]$SubscriptionId,[string]$ServerId) { Invoke-AzRestRead $SubscriptionId "$ServerId/administrators/ActiveDirectory?api-version=2025-01-01" 'Read SQL administrator REST resource' }
function Wait-Admin([string]$SubscriptionId,[string]$ServerId,[object]$Expected,[int]$Seconds=180) { $same=0;for($i=0;$i -lt [Math]::Max(1,[int]($Seconds/5));$i++){ $a=Get-Admin $SubscriptionId $ServerId;if(Test-Admin $a $Expected){$same++;if($same -ge 2){return $a}}else{$same=0};Start-Sleep -Seconds 5 };throw 'ADMIN_REST_PROPAGATION_NOT_VERIFIED' }
function Get-RoleAssignments([string]$SubscriptionId,[string]$Principal,[string]$Scope) { @(Invoke-AzReadJson @('role','assignment','list','--subscription',$SubscriptionId,'--assignee-object-id',$Principal,'--scope',$Scope,'--all','--include-inherited','--fill-principal-name','false','--output','json') 'Read effective ACR role assignments') }
function AssignmentIds([object[]]$Items) { @($Items|ForEach-Object{[string]$_.id}|Sort-Object -Unique) }
function Same-Set([object[]]$A,[object[]]$B) { $aa=@($A|ForEach-Object{[string]$_}|Sort-Object);$bb=@($B|ForEach-Object{[string]$_}|Sort-Object);$aa.Count -eq $bb.Count -and @(Compare-Object $aa $bb).Count -eq 0 }
function Set-UnknownSqlState { $script:MutationState.SQL_MUTATION_STATE='UNKNOWN_REQUIRES_READ_ONLY_ADJUDICATION';foreach($k in @('SQL_CONNECTION_ATTEMPTS','SQL_CREATE_USER_MUTATIONS','SQL_ROLE_MUTATIONS','SQL_PERMISSION_GRANTS','SQL_DDL_MUTATIONS','SQL_DML_MUTATIONS')){$script:MutationCounts[$k]='UNKNOWN'} }

$BootstrapPython=@'
import json,os,sys
r={"sql_connection_attempts":0,"sql_connection_succeeded":False,"sql_login":"NOT_EXECUTED","sql_target_db":"NOT_EXECUTED","sql_required_permission":"NOT_EXECUTED","sql_ddl_executed":False,"sql_dml_executed":False,"api_mutations":0,"migration_mutations":0,"role_mutations":0,"permission_grants":0,"sql_ddl_mutations":0,"sql_dml_mutations":0,"sql_mutations":[],"bootstrap_principal_absent":False,"post_verification":False,"api_user_state":"NOT_EXECUTED","migration_user_state":"NOT_EXECUTED","sql_mutation_state":"KNOWN","error_class":"","error_message":""}
cn=None
def emit(): print("PROPOSALOPS_V25_RESULT="+json.dumps(r,sort_keys=True,separators=(",",":")))
try:
 import pyodbc
 r["sql_connection_attempts"]=1
 cs=f"DRIVER={{ODBC Driver 18 for SQL Server}};Server=tcp:{os.environ['SQL_HOST']},1433;Database={os.environ['SQL_DATABASE']};Authentication=ActiveDirectoryMsi;UID={os.environ['SQL_ODBC_UID']};Encrypt=yes;TrustServerCertificate=no;Connection Timeout=30;"
 cn=pyodbc.connect(cs,autocommit=True);r["sql_connection_succeeded"]=True;cur=cn.cursor()
 r["sql_login"]="PASS" if cur.execute("SELECT 1").fetchone()[0]==1 else "FAIL"
 r["sql_target_db"]="PASS" if cur.execute("SELECT DB_NAME()").fetchone()[0]==os.environ["SQL_DATABASE"] else "FAIL"
 r["sql_required_permission"]="PASS" if int(cur.execute("SELECT HAS_PERMS_BY_NAME(DB_NAME(),'DATABASE','ALTER ANY USER')").fetchone()[0])==1 else "FAIL"
 def sid(cid): return cur.execute("SELECT CONVERT(varchar(34),CONVERT(varbinary(16),CONVERT(uniqueidentifier, ?)),1)",cid).fetchone()[0].lower()
 def inspect(n):
  x=cur.execute("SELECT name,type,CONVERT(varchar(34),sid,1) FROM sys.database_principals WHERE name=?",n).fetchone()
  roles=[str(z[0]) for z in cur.execute("SELECT rp.name FROM sys.database_role_members drm JOIN sys.database_principals rp ON rp.principal_id=drm.role_principal_id JOIN sys.database_principals mp ON mp.principal_id=drm.member_principal_id WHERE mp.name=?",n).fetchall()]
  perms=[str(z[0]) for z in cur.execute("SELECT permission_name FROM sys.database_permissions WHERE grantee_principal_id=USER_ID(?) AND state IN ('G','W')",n).fetchall()]
  return x,roles,perms
 r["bootstrap_principal_absent"]=cur.execute("SELECT 1 FROM sys.database_principals WHERE name='proposalops_bootstrap_uami'").fetchone() is None
 targets=[("proposalops_api_uami",os.environ["API_CLIENT_ID"],["db_datareader","db_datawriter"],set(),False),("proposalops_migration_uami",os.environ["MIGRATION_CLIENT_ID"],["db_datareader","db_datawriter","db_ddladmin"],{"VIEW DEFINITION"},True)]
 states=[]
 for n,cid,required,required_perms,view in targets:
  x,roles,perms=inspect(n);expected=sid(cid)
  if x is not None and (x[1]!="E" or str(x[2]).lower()!=expected): raise RuntimeError("existing principal mismatch")
  if "db_owner" in roles or (n=="proposalops_api_uami" and "db_ddladmin" in roles): raise RuntimeError("forbidden role present")
