  states.append((n,required,required_perms,x,roles,perms,expected))
 if r["sql_login"]!="PASS" or r["sql_target_db"]!="PASS" or r["sql_required_permission"]!="PASS" or not r["bootstrap_principal_absent"]: raise RuntimeError("pre-DDL gate failed")
 for n,required,required_perms,x,roles,perms,expected in states:
  if x is None:
   cur.execute(f"CREATE USER [{n}] WITH SID={expected}, TYPE=E");r["sql_ddl_executed"]=True;r["sql_ddl_mutations"]+=1;r["sql_mutations"].append(f"CREATE USER {n}")
   if n=="proposalops_api_uami":r["api_mutations"]+=1
   else:r["migration_mutations"]+=1
  for role in required:
   if role not in roles: cur.execute(f"ALTER ROLE [{role}] ADD MEMBER [{n}]");r["sql_ddl_executed"]=True;r["role_mutations"]+=1;r["sql_ddl_mutations"]+=1;r["sql_mutations"].append(f"ALTER ROLE {role} ADD MEMBER {n}")
  if required_perms and "VIEW DEFINITION" not in perms: cur.execute(f"GRANT VIEW DEFINITION TO [{n}]");r["sql_ddl_executed"]=True;r["permission_grants"]+=1;r["sql_ddl_mutations"]+=1;r["sql_mutations"].append(f"GRANT VIEW DEFINITION TO {n}")
 for n,required,required_perms,x,roles,perms,expected in states:
  y,actual,actual_perms=inspect(n)
  if y is None or y[1]!="E" or str(y[2]).lower()!=expected or set(actual)!=set(required) or set(actual_perms)!=required_perms: raise RuntimeError("post principal verification failed")
  r["api_user_state" if n=="proposalops_api_uami" else "migration_user_state"]="PASS"
 r["sql_dml_mutations"]=0;r["post_verification"]=True;emit();sys.exit(0)
except Exception as e:
 r["error_class"]=type(e).__name__;r["error_message"]=str(e)[:240];r["sql_dml_mutations"]=0 if not r["sql_dml_executed"] else r["sql_dml_mutations"];emit();sys.exit(1)
finally:
 if cn is not None: cn.close()
'@

function New-JobYaml([string]$Name,[string]$Identity,[string]$EnvironmentId,[string]$Registry,[string]$TenantId,[string]$SqlFqdn,[string]$BootstrapPrincipal,[string]$ApiClient,[string]$MigrationClient){
    $argsJson=ConvertTo-Json ([string[]]@('-c',$BootstrapPython)) -Compress
    $env=@("SQL_HOST=$SqlFqdn","SQL_DATABASE=$Database","SQL_ODBC_UID=$BootstrapPrincipal","API_CLIENT_ID=$ApiClient","MIGRATION_CLIENT_ID=$MigrationClient","AZURE_TENANT_ID=$TenantId",'SYNTHETIC_ONLY=true','REAL_DATA_ALLOWED=false')
    $envJson=ConvertTo-Json ([object[]]($env|ForEach-Object{$p=$_.IndexOf('=');[ordered]@{name=$_.Substring(0,$p);value=$_.Substring($p+1)}})) -Compress
    $identityJson=ConvertTo-Json ([ordered]@{type='UserAssigned';userAssignedIdentities=[ordered]@{$Identity=@{}}}) -Compress
    $yaml=@"
location: UAE North
properties:
  environmentId: $EnvironmentId
  configuration:
    manualTriggerConfig:
      parallelism: 1
      replicaCompletionCount: 1
    replicaRetryLimit: 0
    replicaTimeout: 300
    triggerType: Manual
    registries:
      - server: $Registry
        identity: $Identity
  template:
    containers:
      - name: main
        image: $ExpectedImage
        command: ["python"]
        args: $argsJson
        env: $envJson
        resources:
          cpu: 0.5
          memory: 1Gi
identity: $identityJson
tags: {"application":"ProposalOps","environment":"AZURE-PREPROD","synthetic-only":"true","commissioning":"v2.5-r5"}
"@
    $p=Join-Path ([IO.Path]::GetTempPath()) "proposalops-v25-r5-$RunId.yaml"
    $yaml|Set-Content -LiteralPath $p -Encoding utf8
    $p
}
function Create-OneJob([string]$Name,[string]$Identity,[string]$EnvironmentId,[string]$Registry,[string]$TenantId,[string]$SqlFqdn,[string]$BootstrapPrincipal,[string]$ApiClient,[string]$MigrationClient){$p=New-JobYaml $Name $Identity $EnvironmentId $Registry $TenantId $SqlFqdn $BootstrapPrincipal $ApiClient $MigrationClient;$script:JobCreateAttempted=$true;$script:MutationState.BOOTSTRAP_JOB_CREATE_ATTEMPTED=$true;Invoke-AzMutation @('containerapp','job','create','--subscription',$SubscriptionName,'--resource-group',$RG,'--name',$Name,'--yaml',$p,'--output','json') "Create exactly one R5 Job $Name" 'BOOTSTRAP_JOB_CREATES'|Out-Null;$script:JobCreated=$true;$script:MutationState.BOOTSTRAP_JOB_CREATED=$true}
function Start-OneJob([string]$Name,[string]$Subscription){
    $before=@(Invoke-AzReadJson @('containerapp','job','execution','list','--subscription',$Subscription,'--resource-group',$RG,'--name',$Name,'--output','json') 'Read executions before R5 start')
    $beforeNames=@($before|ForEach-Object{[string]$_.name})
    $script:ExecutionStartAttempted=$true;$script:MutationState.BOOTSTRAP_JOB_EXECUTION_START_ATTEMPTED=$true;$script:AzureAttemptConsumed=$true
    $raw=Invoke-AzMutation @('containerapp','job','start','--subscription',$Subscription,'--resource-group',$RG,'--name',$Name,'--output','json') 'Start exactly one R5 Job execution' 'BOOTSTRAP_JOB_EXECUTIONS'
